  (* [comment removed for export] *)
  Lemma pxd_D : forall regs m (pix : Z),
    getr regs 8 = Z_to_bv 64 pix ->
    exists regs',
      msteps SEGS (mkst regs (0x6cba8 : word) m rom) (mkst regs' (0xfa374 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 pix /\ getr regs' 1 = Z_to_bv 64 0x6cbb0
      /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
Proof.
